--- a/internal/generatedgo/code/base/base.go
+++ b/internal/generatedgo/code/base/base.go
@@ -11804,6 +11804,7 @@ func (o osFS) Link(a, b string) error                    { return os.Link(o.join
 type MemFS struct {
 	mu   sync.Mutex
 	root *memNode
+	cow  *cowAudit
 }

 // NewMemFS returns an empty in-memory filesystem with a root directory.
@@ -11820,6 +11821,7 @@ type memNode struct {
 	modTime  time.Time
 	data     []byte
 	children map[string]*memNode
+	cow      *cowNode
 }

 func memSplit(name string) []string {
@@ -11895,6 +11897,7 @@ func (fsys *MemFS) OpenFile(name string, flag int, perm os.FileMode) (File, erro
 			return nil, &fs.PathError{Op: "open", Path: name, Err: fs.ErrExist}
 		}
 		if flag&os.O_TRUNC != 0 && !node.dir {
+			fsys.cowTouch(node, "open-truncate", 0, 0)
 			node.data = node.data[:0]
 			node.modTime = time.Now()
 		}
@@ -12090,6 +12093,7 @@ func (f *memFile) Allocate(end int64) error {
 		return syscall.EISDIR
 	}
 	if end > int64(len(f.node.data)) {
+		f.fsys.cowTouch(f.node, "allocate", end, 0)
 		f.node.data = resizeMemData(f.node.data, end)
 		f.node.modTime = time.Now()
 	}
@@ -12145,6 +12149,7 @@ func (f *memFile) ReadAt(p []byte, off int64) (int, error) {

 // writeAt grows node.data as needed and writes p at off. Caller holds the lock.
 func (f *memFile) writeAt(p []byte, off int64) int {
+	f.fsys.cowTouch(f.node, "write", off+int64(len(p)), len(p))
 	end := off + int64(len(p))
 	if end > int64(len(f.node.data)) {
 		f.node.data = resizeMemData(f.node.data, end)
@@ -12185,6 +12190,7 @@ func (f *memFile) Seek(offset int64, whence int) (int64, error) {
 func (f *memFile) Truncate(size int64) error {
 	f.fsys.mu.Lock()
 	defer f.fsys.mu.Unlock()
+	f.fsys.cowTouch(f.node, "truncate", size, 0)
 	f.node.data = resizeMemData(f.node.data, size)
 	f.node.modTime = time.Now()
 	return nil
